{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Urapidil, the highest-transfer analogue (0.9755), has a human oral bioavailability of 78%; its methoxyphenyl-piperazine framework is directly relevant to the query's piperazine and methoxyphenyl ether, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Metoprolol, a close aryloxypropanolamine analogue (transfer 0.952), shows 55 ± 7% systemic availability after oral dosing, supporting high oral bioavailability for the query's shared core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Pamatolol, another aryloxypropanolamine (transfer 0.9367), shows essentially complete oral bioavailability (64.9–103.5%), supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Bosentan (transfer 0.9523) has approximately 50% absolute oral bioavailability in healthy volunteers, supporting high bioavailability despite its more complex polar structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Propranolol, sharing the aryloxypropanolamine core (transfer 0.9484), had 18.9 ± 3.8% absolute bioavailability in normal volunteers, providing threshold-relevant contradictory evidence of possible first-pass liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transfer evidence, led by urapidil (78% F) and supported by metoprolol, pamatolol, and bosentan, indicates F ≥ 20%. Propranolol provides a contradictory first-pass liability signal, but the query's piperazine/amide substitution and the preponderance of high-F analogues shift the balance toward high bioavailability.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the query molecule.",
    "First-pass metabolism and transporter-mediated efflux cannot be fully excluded from structure alone.",
    "Encainide and propranolol show substantial interindividual variability, so population extremes may fall below 20% even if the mean is above threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

